"""User-authored conversation-session configuration.

A project's ``agent.yml`` may carry a ``session_config`` block controlling
conversation-session lifecycle: how long a session stays alive and whether a new
session auto-starts once the previous one expires.  It is parsed once into a
frozen :class:`SessionSpec` at model load by
``rasa.mantle.model_archive.bootstrap`` (from the packaged snapshot's
``agent.yml``) and exposed to the shared session lifecycle via
``MantleMessageProcessor.session_config`` (see ENG-2875).

The engine owns its state through the memory layer rather than tracker slots, so the
v1 ``carry_over_slots`` knob has no effect and is intentionally not authorable
here.  The :class:`~rasa.shared.core.domain.SessionConfig` returned by
:meth:`SessionSpec.to_session_config` fills it with the engine default so shared
consumers keep a complete tuple.
"""

from __future__ import annotations

from typing import Any, Mapping, Optional

import pydantic
from pydantic import BaseModel, ConfigDict, field_validator

from rasa.exceptions import ValidationError
from rasa.shared.constants import (
    DEFAULT_CARRY_OVER_SLOTS_TO_NEW_SESSION,
    DEFAULT_SESSION_EXPIRATION_TIME_IN_MINUTES,
    DEFAULT_START_SESSION_AFTER_EXPIRY,
)
from rasa.shared.core.domain import SessionConfig

_SESSION_CONFIG_KEY = "session_config"


class SessionSpec(BaseModel):
    """User-authored conversation-session settings from the agent.yml."""

    model_config = ConfigDict(frozen=True, extra="ignore")

    session_expiration_time: float = DEFAULT_SESSION_EXPIRATION_TIME_IN_MINUTES
    """Session lifetime in minutes; ``0`` disables session expiry entirely."""

    start_session_after_expiry: bool = DEFAULT_START_SESSION_AFTER_EXPIRY
    """Whether a new session auto-starts on the next message after expiry."""

    @field_validator("session_expiration_time")
    @classmethod
    def _expiration_time_non_negative(cls, value: float) -> float:
        """Reject a negative expiration time (``0`` means sessions disabled)."""
        if value < 0:
            # Raise a rasa (RasaException-derived) error rather than a bare
            # ValueError so config failures surface as typed domain exceptions.
            # pydantic propagates non-ValueError exceptions from validators, so
            # this reaches the caller directly on both the parse and the
            # direct-construction paths.
            raise ValidationError(
                code="config.session.invalid_expiration_time",
                event_info=(
                    "Invalid session configuration in agent.yml: "
                    "session_config.session_expiration_time must be >= 0 "
                    "(0 disables session expiry)."
                ),
            )
        return value

    def to_session_config(self) -> SessionConfig:
        """Convert to the engine's :class:`SessionConfig` tuple.

        ``carry_over_slots`` is not authorable in the new engine (no-op with the memory
        layer); it is filled with the engine default so shared session consumers
        receive a complete tuple.

        TODO: Remove this conversion once the CALM v1 engine is deprecated. The
        shared session lifecycle depends on the ``SessionConfig`` tuple only
        because v1 sources it from the domain; once v1 is gone the session code
        should consume this :class:`SessionSpec` directly instead.
        """
        return SessionConfig(
            session_expiration_time=self.session_expiration_time,
            carry_over_slots=DEFAULT_CARRY_OVER_SLOTS_TO_NEW_SESSION,
            start_session_after_expiry=self.start_session_after_expiry,
        )


def session_spec_from_config(
    config_data: Optional[Mapping[str, Any]],
) -> SessionSpec:
    """Parse the session settings from a top-level agent.yml mapping.

    Reads the ``session_config`` block from the top level of agent.yml.  A
    missing/empty config or absent block yields a default spec so that projects
    without session config keep working.  A malformed section raises a fail-fast
    :class:`ValidationError`.
    """
    if not config_data:
        return SessionSpec()

    session_section = config_data.get(_SESSION_CONFIG_KEY)
    if session_section is None:
        return SessionSpec()

    try:
        return SessionSpec.model_validate(session_section)
    except pydantic.ValidationError as error:
        raise ValidationError(
            code="config.session.invalid_section",
            event_info=f"Invalid session configuration in agent.yml: {error}",
        ) from error
